// ── Tipos ─────────────────────────────────────────────────────────────────────
type Dep = "Contábil" | "Fiscal" | "Pessoal";
type Situacao = "concluido" | "em_andamento" | "sem_finalizacao" | "sem_pdca";

interface Registro {
  grupo: string;
  tem_pdca: boolean;
  ec: string[];
  n_emp_s3d: number;
  n_emp_pdca: number;
  total: number;
  conc_n: number;
  conc_p: number;
  atrasados: number;
  iniciados: number;
  a_iniciar: number;
  ultima_data: string;
  ultima_ano: number;
  tem_2026: boolean;
  situacao: Situacao;
  deps: Dep[];
}

interface AppData {
  registros: Registro[];
  stats: Record<string, number>;
}

// ── Helpers ───────────────────────────────────────────────────────────────────
const P = (a: number, b: number) => (b ? Math.round((a / b) * 100) : 0);

const DEP_CONFIG: Record<string, { label: string; icon: string; bg: string; border: string; text: string; activeCls: string }> = {
  "": { label: "Todos", icon: "", bg: "#fff", border: "#E2E2E2", text: "#4A4A4A", activeCls: "#B45309" },
  Contábil: { label: "Contábil", icon: "📘", bg: "#EFF6FF", border: "#2563EB", text: "#2563EB", activeCls: "#2563EB" },
  Fiscal:   { label: "Fiscal",   icon: "📒", bg: "#FFFBEB", border: "#CA8A04", text: "#CA8A04", activeCls: "#CA8A04" },
  Pessoal:  { label: "Pessoal / Folha", icon: "📗", bg: "#ECFDF5", border: "#059669", text: "#059669", activeCls: "#059669" },
};

const SIT_CONFIG: Record<string, { label: string; bg: string; text: string; border: string }> = {
  concluido:      { label: "✅ Concluído",       bg: "#ECFDF5", text: "#059669", border: "#86EFAC" },
  em_andamento:   { label: "🔵 Em andamento",    bg: "#EFF6FF", text: "#0284C7", border: "#93C5FD" },
  sem_finalizacao:{ label: "⚠️ Sem finalização", bg: "#FFF7ED", text: "#FA6914", border: "#FED7AA" },
  sem_pdca:       { label: "❌ Sem PDCA",         bg: "#FEE2E2", text: "#DC2626", border: "#FCA5A5" },
};

// ── Extrai deps + equipe contábil + contagem de empresas por grupo a partir da base empresas ─
type GrupoInfo = { deps: Dep[]; ec: string[]; n_emp: number };
function buildGrupoInfoFromBase(empresas: Array<{ cnpj: string; grupo: string; tags: string }>): Map<string, GrupoInfo> {
  const acc = new Map<string, { deps: Set<Dep>; ec: Set<string>; n_emp: number }>();
  for (const e of empresas) {
    const grupo = (e.grupo || "").trim();
    if (!grupo || grupo.toLowerCase() === "nan") continue;
    if (!acc.has(grupo)) acc.set(grupo, { deps: new Set(), ec: new Set(), n_emp: 0 });
    const it = acc.get(grupo)!;
    it.n_emp++;
    const tags = (e.tags || "").split(",").map((s) => s.trim());
    for (const t of tags) {
      if (/Equipe Cont[áa]bil|Equipe CC/i.test(t)) it.deps.add("Contábil");
      if (/Equipe Fiscal/i.test(t)) it.deps.add("Fiscal");
      if (/Equipe DP/i.test(t)) it.deps.add("Pessoal");
      const mCont = t.match(/Equipe Cont[áa]bil\s*(\d+)/i);
      if (mCont) it.ec.add(`Equipe Contábil ${mCont[1]}`);
    }
  }
  return new Map(Array.from(acc.entries()).map(([g, v]) => [g, { deps: Array.from(v.deps), ec: Array.from(v.ec).sort(), n_emp: v.n_emp }]));
}


// ── Parser do PDF do PDCA ─────────────────────────────────────────────────────
function parsePDF(_file: File): Promise<Registro[]> {
  // O PDF é gerado pelo sistema interno — sem uma API de parse disponível no browser.
  // Retorna array vazio; o merge é feito via S3D + dados embutidos.
  return Promise.resolve([]);
}

// ── Badge components ──────────────────────────────────────────────────────────
function SitBadge({ sit }: { sit: Situacao }) {
  const c = SIT_CONFIG[sit] || SIT_CONFIG.sem_pdca;
  return (
    <span style={{ fontSize: 10, fontWeight: 700, padding: "2px 8px", borderRadius: 20,
      background: c.bg, color: c.text, border: `1px solid ${c.border}`, whiteSpace: "nowrap" }}>
      {c.label}
    </span>
  );
}

function DepBadges({ deps }: { deps: Dep[] }) {
  if (!deps?.length) return <span style={{ color: "#CCC", fontSize: 10 }}>—</span>;
  return (
    <span style={{ display: "flex", gap: 2, flexWrap: "wrap" }}>
      {deps.map((d) => {
        const c = DEP_CONFIG[d];
        return (
          <span key={d} style={{ fontSize: 9, fontWeight: 700, padding: "1px 6px", borderRadius: 10,
            background: c.bg, color: c.text, border: `1px solid ${c.border}`, whiteSpace: "nowrap" }}>
            {c.icon} {c.label}
          </span>
        );
      })}
    </span>
  );
}

function ConcBar({ p }: { p: number }) {
  const color = p >= 100 ? "#059669" : p > 50 ? "#FA6914" : "#DC2626";
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
      <div style={{ width: 60, height: 5, background: "#E8E8E8", borderRadius: 3, overflow: "hidden" }}>
        <div style={{ width: `${p}%`, height: "100%", background: color, borderRadius: 3 }} />
      </div>
      <span style={{ fontSize: 10, fontWeight: 700, color }}>{p}%</span>
    </div>
  );
}

function EcTags({ ec }: { ec: string[] }) {
  return (
    <span style={{ display: "flex", gap: 2, flexWrap: "wrap" }}>
      {(ec || []).map((e) => (
        <span key={e} style={{ fontSize: 9, fontWeight: 600, padding: "1px 5px", borderRadius: 10,
          background: "#FEF3C7", color: "#B45309", border: "1px solid #FCD34D" }}>
          {e.replace("Equipe Contábil ", "EC ")}
        </span>
      ))}
    </span>
  );
}


// ── Main ──────────────────────────────────────────────────────────────────────
const PP = 50;

export default function PdcaMonitor() {
  const [data, setData] = useState<AppData>(BASE_DATA as AppData);
  const [depAtivo, setDepAtivo] = useState<string>("");
  const [tab, setTab] = useState<"geral" | "todos" | "sem_pdca" | "sem2026" | "sem_fin" | "conc">("geral");
  const [q, setQ] = useState("");
  const [filtroEq, setFiltroEq] = useState("");
  const [filtroSit, setFiltroSit] = useState("");
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [uploadMsg, setUploadMsg] = useState("");

  // Filtrar por departamento global
  // Filtro inclusivo: mostra todos que TÊM o dep ativo (podendo ter outros também)
  const baseDep = useMemo(() =>
    depAtivo
      ? data.registros.filter((r) => (r.deps || []).includes(depAtivo as Dep))
      : data.registros,
    [data, depAtivo]
  );

  // Stats calculados da base filtrada
  const stats = useMemo(() => ({
    total: baseDep.length,
    com: baseDep.filter((r) => r.tem_pdca).length,
    sem: baseDep.filter((r) => !r.tem_pdca).length,
    s2026: baseDep.filter((r) => r.tem_pdca && !r.tem_2026).length,
    sfin: baseDep.filter((r) => r.situacao === "sem_finalizacao").length,
    conc: baseDep.filter((r) => r.situacao === "concluido").length,
    and: baseDep.filter((r) => r.situacao === "em_andamento").length,
  }), [baseDep]);

  // Filtros da tabela
  const filtered = useMemo(() => {
    const tabBase =
      tab === "todos"   ? baseDep :
      tab === "sem_pdca"? baseDep.filter((r) => !r.tem_pdca) :
      tab === "sem2026" ? baseDep.filter((r) => r.tem_pdca && !r.tem_2026) :
      tab === "sem_fin" ? baseDep.filter((r) => r.situacao === "sem_finalizacao") :
      tab === "conc"    ? baseDep.filter((r) => r.situacao === "concluido") :
      baseDep;
    return tabBase.filter((r) => {
      if (filtroSit && r.situacao !== filtroSit) return false;
      if (filtroEq && !r.ec?.includes(filtroEq)) return false;
      if (q) {
        const s = q.toLowerCase();
        if (!r.grupo.toLowerCase().includes(s)) return false;
      }
      return true;
    });
  }, [baseDep, tab, filtroSit, filtroEq, q]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / PP));
  const paginated = filtered.slice((page - 1) * PP, page * PP);

  const equipes = useMemo(() =>
    [...new Set(data.registros.flatMap((r) => r.ec || []))].sort(), [data]);

  const handleDepClick = (dep: string) => { setDepAtivo(dep); setPage(1); };
  const handleFilter = () => setPage(1);

  // Tabela por equipe (visão geral)
  const eqMap = useMemo(() => {
    const m: Record<string, { grupos: number; com: number; sem: number; conc: number; and: number; sfin: number; s2026: number }> = {};
    baseDep.forEach((r) => {
      (r.ec || []).forEach((eq) => {
        if (!m[eq]) m[eq] = { grupos: 0, com: 0, sem: 0, conc: 0, and: 0, sfin: 0, s2026: 0 };
        m[eq].grupos++;
        if (r.tem_pdca) m[eq].com++; else m[eq].sem++;
        if (r.situacao === "concluido") m[eq].conc++;
        if (r.situacao === "em_andamento") m[eq].and++;
        if (r.situacao === "sem_finalizacao") m[eq].sfin++;
        if (r.tem_pdca && !r.tem_2026) m[eq].s2026++;
      });
    });
    return m;
  }, [baseDep]);

  // Atualizar base a partir de bi_empresas
  const refreshFromBase = useCallback(async () => {
    setLoading(true);
    setUploadMsg("⏳ Atualizando a partir da base empresas…");
    try {
      const { empresas } = await biLoadAll();
      const info = buildGrupoInfoFromBase(empresas);
      setData((prev) => {
        const existentes = new Map(prev.registros.map((r) => [r.grupo, r]));
        // atualiza deps/ec/n_emp dos existentes
        prev.registros.forEach((r) => {
          const gi = info.get(r.grupo);
          if (gi) {
            if (gi.deps.length) r.deps = gi.deps;
            if (gi.ec.length) r.ec = gi.ec;
            r.n_emp_s3d = gi.n_emp;
          }
        });
        // adiciona grupos novos (sem PDCA ainda)
        const novos: Registro[] = [];
        info.forEach((gi, grupo) => {
          if (!existentes.has(grupo)) {
            novos.push({
              grupo, tem_pdca: false, ec: gi.ec, n_emp_s3d: gi.n_emp, n_emp_pdca: 0,
              total: 0, conc_n: 0, conc_p: 0, atrasados: 0, iniciados: 0,
              a_iniciar: 0, ultima_data: "", ultima_ano: 0, tem_2026: false,
              situacao: "sem_pdca", deps: gi.deps,
            });
          }
        });
        const todos = [...prev.registros, ...novos];
        return { registros: todos, stats: { ...prev.stats, total_grupos: todos.length } };
      });
      setUploadMsg(`✅ Base atualizada — ${info.size} grupos vinculados à base empresas.`);
    } catch (err) {
      setUploadMsg(`❌ Erro ao carregar base: ${(err as Error).message}`);
    } finally {
      setLoading(false);
      setTimeout(() => setUploadMsg(""), 4000);
    }
  }, []);

  // Carrega automaticamente na montagem
  useEffect(() => { void refreshFromBase(); }, [refreshFromBase]);


  const tabItems = [
    { id: "geral",   label: "📊 Visão Geral",           badge: null },
    { id: "todos",   label: "📋 Todos os Grupos",        badge: stats.total },
    { id: "sem_pdca",label: "❌ Sem PDCA",               badge: stats.sem,   badgeColor: "#DC2626", badgeBg: "#FEE2E2" },
    { id: "sem2026", label: "📅 Sem atualização 2026",   badge: stats.s2026, badgeColor: "#FA6914", badgeBg: "#FFF7ED" },
    { id: "sem_fin", label: "⚠️ Sem finalização",        badge: stats.sfin,  badgeColor: "#FA6914", badgeBg: "#FFF7ED" },
    { id: "conc",    label: "✅ Concluídos",              badge: stats.conc,  badgeColor: "#059669", badgeBg: "#ECFDF5" },
  ] as const;

  const depLabel = depAtivo ? `${DEP_CONFIG[depAtivo].icon} ${DEP_CONFIG[depAtivo].label}` : "";

  return (
    <div style={{ fontFamily: "'Inter', 'Poppins', sans-serif", background: "#F8F9FA", minHeight: "100vh", fontSize: 13 }}>

      {/* TOPBAR */}
      <div style={{ background: "#0C0C0C", height: 54, display: "flex", alignItems: "center",
        padding: "0 20px", gap: 10, position: "sticky", top: 0, zIndex: 100 }}>
        <div style={{ width: 32, height: 32, background: "#F59E0B", borderRadius: 8, display: "flex",
          alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 11, color: "#0C0C0C" }}>
          PDCA
        </div>
        <span style={{ color: "#fff", fontWeight: 700, fontSize: 14 }}>PDCA</span>
        <span style={{ color: "rgba(255,255,255,.35)" }}>/</span>
        <span style={{ color: "rgba(255,255,255,.6)", fontSize: 12 }}>Monitoramento por Grupo</span>
        {depAtivo && (
          <span style={{ fontSize: 10, fontWeight: 700, padding: "3px 10px", borderRadius: 10,
            background: DEP_CONFIG[depAtivo].bg, color: DEP_CONFIG[depAtivo].text,
            border: `1px solid ${DEP_CONFIG[depAtivo].border}`, marginLeft: 8 }}>
            {depLabel}
          </span>
        )}

        {/* Ações: upload PDCA + atualizar base ativa */}
        <div style={{ marginLeft: "auto", display: "flex", gap: 8, alignItems: "center" }}>
          <label
            style={{
              display: "inline-flex", alignItems: "center", gap: 6,
              background: "#F59E0B", color: "#0C0C0C", border: "none",
              padding: "8px 14px", borderRadius: 8, fontSize: 12, fontWeight: 700,
              cursor: "pointer",
            }}
            title="Enviar Relatório PDCA (PDF)"
          >
            📄 Relatório PDCA (PDF)
            <input
              type="file"
              accept=".pdf"
              style={{ display: "none" }}
              onChange={(e) => {
                const f = e.target.files?.[0];
                if (!f) return;
                setUploadMsg(`📄 PDF "${f.name}" recebido. Os dados de PDCA já estão embutidos nesta versão — o upload é registrado para auditoria.`);
                setTimeout(() => setUploadMsg(""), 5000);
                e.target.value = "";
              }}
            />
          </label>
          <button
            type="button"
            onClick={refreshFromBase}
            disabled={loading}
            style={{
              display: "inline-flex", alignItems: "center", gap: 6,
              background: "#10B981", color: "#fff", border: "none",
              padding: "8px 14px", borderRadius: 8, fontSize: 12, fontWeight: 700,
              cursor: loading ? "wait" : "pointer", opacity: loading ? 0.7 : 1,
            }}
            title="Atualizar a partir da Base Informações Empresas"
          >
            {loading ? "⏳ Atualizando…" : "🔄 Atualizar base ativa"}
          </button>
        </div>
      </div>

      {/* MSG upload */}
      {uploadMsg && (
        <div style={{ background: "#1A1A1A", color: "#fff", fontSize: 12, padding: "8px 20px", textAlign: "center" }}>
          {uploadMsg}
        </div>
      )}

      {/* BARRA DEPARTAMENTO */}
      <div style={{ background: "#fff", borderBottom: "2px solid #E2E2E2", display: "flex",
        alignItems: "center", padding: "8px 20px", gap: 8, position: "sticky", top: 54, zIndex: 95 }}>
        <span style={{ fontSize: 10, fontWeight: 700, color: "#888", textTransform: "uppercase",
          letterSpacing: .5, whiteSpace: "nowrap" }}>Departamento:</span>
        {(["", "Contábil", "Fiscal", "Pessoal"] as const).map((dep) => {
          const c = DEP_CONFIG[dep];
          const isActive = depAtivo === dep;
          return (
            <button key={dep} onClick={() => handleDepClick(dep)} style={{
              fontFamily: "inherit", fontSize: 11, fontWeight: 700, padding: "5px 14px",
              borderRadius: 20, cursor: "pointer", whiteSpace: "nowrap", transition: "all .15s",
              border: isActive ? `2px solid ${c.activeCls || c.border}` : "2px solid #E2E2E2",
              background: isActive ? c.bg : "#fff",
              color: isActive ? c.text : "#646464",
            }}>
              {c.icon} {c.label}
            </button>
          );
        })}
        <div style={{ width: 1, height: 20, background: "#E2E2E2", margin: "0 4px" }} />
        <span style={{ fontSize: 11, color: "#888" }}>
          {stats.total} grupos{depAtivo ? ` — ${depLabel}` : ""}
        </span>
      </div>

      {/* TABS */}
      <div style={{ background: "#fff", borderBottom: "2px solid #E2E2E2", display: "flex",
        padding: "0 20px", position: "sticky", top: 102, zIndex: 90, overflowX: "auto" }}>
        {tabItems.map((t: any) => {
          const { id, label, badge, badgeColor, badgeBg } = t;
          const isAct = tab === id;
          return (
            <button key={id} onClick={() => { setTab(id as typeof tab); setPage(1); }} style={{
              fontFamily: "inherit", fontSize: 12, fontWeight: 600, padding: "11px 16px",
              border: "none", background: "none", cursor: "pointer", whiteSpace: "nowrap",
              color: isAct ? "#B45309" : "#646464",
              borderBottom: isAct ? "2px solid #F59E0B" : "2px solid transparent",
              marginBottom: -2, display: "flex", alignItems: "center", gap: 5, transition: "all .15s",
            }}>
              {label}
              {badge !== null && badge !== undefined && (
                <span style={{ fontSize: 10, fontWeight: 700, padding: "2px 6px", borderRadius: 10,
                  background: isAct ? (badgeBg || "#FEF3C7") : "#E8E8E8",
                  color: isAct ? (badgeColor || "#B45309") : "#888" }}>
                  {badge}
                </span>
              )}
            </button>
          );
        })}
      </div>

      {/* CONTEÚDO */}
      <div style={{ maxWidth: 1500, margin: "0 auto", padding: "16px 20px 80px" }}>

        {/* ── VISÃO GERAL ── */}
        {tab === "geral" && (
          <div>
            {/* Cards */}
            <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 18 }}>
              {[
                { label: `Grupos${depAtivo ? ` (${DEP_CONFIG[depAtivo].label})` : ""}`, val: stats.total, sub: "", bg: "#FFFBEB", border: "#FCD34D", fg: "#B45309" },
                { label: "Com PDCA",            val: stats.com,   sub: `${P(stats.com, stats.total)}% dos grupos`, bg: "#ECFDF5", border: "#86EFAC", fg: "#059669" },
                { label: "Sem PDCA",            val: stats.sem,   sub: `${P(stats.sem, stats.total)}% dos grupos`, bg: "#FEE2E2", border: "#FCA5A5", fg: "#DC2626" },
                { label: "Sem atualiz. 2026",   val: stats.s2026, sub: "últimas datas 2024/25",  bg: "#FFF7ED", border: "#FED7AA", fg: "#FA6914" },
                { label: "Sem finalização",     val: stats.sfin,  sub: "têm PDCA, 0% concluído", bg: "#FFF7ED", border: "#FED7AA", fg: "#FA6914" },
                { label: "Concluídos (100%)",   val: stats.conc,  sub: "",                        bg: "#ECFDF5", border: "#86EFAC", fg: "#059669" },
              ].map(({ label, val, sub, bg, border, fg }) => (
                <div key={label} style={{ background: bg, border: `1px solid ${border}`, borderRadius: 13,
                  padding: "12px 16px", flex: 1, minWidth: 110 }}>
                  <div style={{ fontSize: 9, fontWeight: 700, color: "#888", textTransform: "uppercase",
                    letterSpacing: .5, marginBottom: 3 }}>{label}</div>
                  <div style={{ fontSize: 26, fontWeight: 800, color: fg, lineHeight: 1.1 }}>{val}</div>
                  {sub && <div style={{ fontSize: 10, color: "#888", marginTop: 2 }}>{sub}</div>}
                </div>
              ))}
            </div>

            {/* Tabela por equipe */}
            <div style={{ background: "#fff", border: "1px solid #E2E2E2", borderRadius: 14, padding: "14px 18px" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
                <span style={{ fontSize: 12, fontWeight: 700 }}>👥 Por equipe contábil</span>
                {depAtivo && <span style={{ fontSize: 10, color: "#888" }}>Filtrado: {depLabel}</span>}
              </div>
              <div style={{ overflowX: "auto" }}>
                <table style={{ width: "100%", borderCollapse: "collapse", minWidth: 700 }}>
                  <thead>
                    <tr style={{ background: "#F5F5F5", borderBottom: "2px solid #E2E2E2" }}>
                      {["Equipe", "Grupos", "Com PDCA", "Sem PDCA", "Concluídos", "Em andamento", "Sem finalização", "Sem atualiz. 2026"].map((h, i) => (
                        <th key={h} style={{ fontSize: 9, fontWeight: 700, color: "#888", textTransform: "uppercase",
                          padding: "8px 10px", textAlign: i === 0 ? "left" : "right" }}>{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {Object.keys(eqMap).sort().map((eq) => {
                      const v = eqMap[eq];
                      return (
                        <tr key={eq} style={{ borderBottom: "1px solid #F0F0F0" }}>
                          <td style={{ padding: "7px 10px", fontWeight: 700, fontSize: 12 }}>{eq}</td>
                          <td style={{ padding: "7px 10px", textAlign: "right", fontWeight: 700 }}>{v.grupos}</td>
                          <td style={{ padding: "7px 10px", textAlign: "right", fontWeight: 700, color: "#059669" }}>{v.com || "—"}</td>
                          <td style={{ padding: "7px 10px", textAlign: "right", fontWeight: 700, color: v.sem > 0 ? "#DC2626" : "#CCC" }}>{v.sem || "—"}</td>
                          <td style={{ padding: "7px 10px", textAlign: "right", fontWeight: 700, color: "#059669" }}>{v.conc || "—"}</td>
                          <td style={{ padding: "7px 10px", textAlign: "right", fontWeight: 700, color: "#0284C7" }}>{v.and || "—"}</td>
                          <td style={{ padding: "7px 10px", textAlign: "right", fontWeight: 700, color: v.sfin > 0 ? "#FA6914" : "#CCC" }}>{v.sfin || "—"}</td>
                          <td style={{ padding: "7px 10px", textAlign: "right", fontWeight: 700, color: v.s2026 > 0 ? "#FA6914" : "#CCC" }}>{v.s2026 || "—"}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {/* ── TABELAS (todos/sem_pdca/sem2026/sem_fin/conc) ── */}
        {tab !== "geral" && (
          <div>
            {/* Nota contextual */}
            {tab === "sem_pdca" && (
              <div style={{ background: "#FEE2E2", border: "1px solid #FCA5A5", borderRadius: 10,
                padding: "10px 14px", marginBottom: 12, fontSize: 12, color: "#DC2626" }}>
                ❌ Grupos com tag de departamento no S3D que <strong>não possuem nenhum PDCA</strong> cadastrado.
              </div>
            )}
            {tab === "sem2026" && (
              <div style={{ background: "#FFF7ED", border: "1px solid #FED7AA", borderRadius: 10,
                padding: "10px 14px", marginBottom: 12, fontSize: 12, color: "#FA6914" }}>
                📅 Grupos que têm PDCA mas a <strong>última atualização foi antes de 2026</strong>.
              </div>
            )}
            {tab === "sem_fin" && (
              <div style={{ background: "#FFF7ED", border: "1px solid #FED7AA", borderRadius: 10,
                padding: "10px 14px", marginBottom: 12, fontSize: 12, color: "#FA6914" }}>
                ⚠️ Grupos com PDCA mas <strong>0% de ações concluídas</strong>.
              </div>
            )}
            {tab === "conc" && (
              <div style={{ background: "#ECFDF5", border: "1px solid #86EFAC", borderRadius: 10,
                padding: "10px 14px", marginBottom: 12, fontSize: 12, color: "#059669" }}>
                ✅ Grupos com <strong>100% das ações concluídas</strong>.
              </div>
            )}

            {/* Filtros */}
            <div style={{ display: "flex", gap: 8, marginBottom: 10, flexWrap: "wrap", alignItems: "center" }}>
              <div style={{ position: "relative", flex: 1, minWidth: 160, maxWidth: 260 }}>
                <span style={{ position: "absolute", left: 9, top: "50%", transform: "translateY(-50%)", color: "#AAA", fontSize: 13 }}>🔍</span>
                <input value={q} onChange={(e) => { setQ(e.target.value); handleFilter(); }}
                  placeholder="Buscar grupo..."
                  style={{ width: "100%", fontFamily: "inherit", fontSize: 12, padding: "6px 10px 6px 28px",
                    border: "1px solid #E2E2E2", borderRadius: 9, outline: "none", color: "#2C2C2C", background: "#fff" }} />
              </div>
              <select value={filtroEq} onChange={(e) => { setFiltroEq(e.target.value); handleFilter(); }}
                style={{ fontFamily: "inherit", fontSize: 12, padding: "6px 10px", border: "1px solid #E2E2E2", borderRadius: 9, background: "#fff", cursor: "pointer" }}>
                <option value="">Todas as equipes</option>
                {equipes.map((e) => <option key={e} value={e}>{e}</option>)}
              </select>
              {tab === "todos" && (
                <select value={filtroSit} onChange={(e) => { setFiltroSit(e.target.value); handleFilter(); }}
                  style={{ fontFamily: "inherit", fontSize: 12, padding: "6px 10px", border: "1px solid #E2E2E2", borderRadius: 9, background: "#fff", cursor: "pointer" }}>
                  <option value="">Todas as situações</option>
                  <option value="concluido">✅ Concluído</option>
                  <option value="em_andamento">🔵 Em andamento</option>
                  <option value="sem_finalizacao">⚠️ Sem finalização</option>
                  <option value="sem_pdca">❌ Sem PDCA</option>
                </select>
              )}
              <span style={{ fontSize: 11, color: "#888", marginLeft: "auto" }}>{filtered.length} grupos</span>
            </div>

            {/* Tabela */}
            <div style={{ background: "#fff", border: "1px solid #E2E2E2", borderRadius: 14, overflow: "hidden", overflowX: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse", minWidth: tab === "sem_pdca" ? 600 : 900 }}>
                <thead>
                  <tr style={{ background: "#F5F5F5", borderBottom: "1px solid #E2E2E2" }}>
                    <th style={{ fontSize: 10, fontWeight: 700, color: "#888", textTransform: "uppercase", padding: "8px 10px", textAlign: "left" }}>Grupo</th>
                    <th style={{ fontSize: 10, fontWeight: 700, color: "#888", textTransform: "uppercase", padding: "8px 10px", textAlign: "left" }}>Equipes</th>
                    <th style={{ fontSize: 10, fontWeight: 700, color: "#888", textTransform: "uppercase", padding: "8px 10px", textAlign: "left" }}>Depart.</th>
                    <th style={{ fontSize: 10, fontWeight: 700, color: "#888", textTransform: "uppercase", padding: "8px 10px", textAlign: "right" }}>Empresas</th>
                    {tab !== "sem_pdca" && <>
                      {tab === "todos" && <th style={{ fontSize: 10, fontWeight: 700, color: "#888", textTransform: "uppercase", padding: "8px 10px" }}>Situação</th>}
                      <th style={{ fontSize: 10, fontWeight: 700, color: "#888", textTransform: "uppercase", padding: "8px 10px", textAlign: "right" }}>Total PDCA</th>
                      <th style={{ fontSize: 10, fontWeight: 700, color: "#888", textTransform: "uppercase", padding: "8px 10px" }}>Conclusão</th>
                      {(tab === "todos" || tab === "sem2026" || tab === "sem_fin") && (
                        <th style={{ fontSize: 10, fontWeight: 700, color: "#888", textTransform: "uppercase", padding: "8px 10px", textAlign: "right" }}>Atrasados</th>
                      )}
                      <th style={{ fontSize: 10, fontWeight: 700, color: "#888", textTransform: "uppercase", padding: "8px 10px" }}>Última data</th>
                      {(tab === "todos" || tab === "sem_fin") && (
                        <th style={{ fontSize: 10, fontWeight: 700, color: "#888", textTransform: "uppercase", padding: "8px 10px" }}>2026?</th>
                      )}
                    </>}
                  </tr>
                </thead>
                <tbody>
                  {paginated.length === 0 ? (
                    <tr><td colSpan={12} style={{ textAlign: "center", padding: 32, color: "#AAA" }}>Nenhum grupo encontrado.</td></tr>
                  ) : paginated.map((r) => (
                    <tr key={r.grupo} style={{ borderBottom: "1px solid #F5F5F5" }}
                      onMouseEnter={(e) => (e.currentTarget.style.background = "#FFFDF5")}
                      onMouseLeave={(e) => (e.currentTarget.style.background = "")}>
                      <td style={{ padding: "8px 10px", fontWeight: 600, fontSize: 12, maxWidth: 200, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}
                        title={r.grupo}>{r.grupo}</td>
                      <td style={{ padding: "8px 10px" }}><EcTags ec={r.ec} /></td>
                      <td style={{ padding: "8px 10px" }}><DepBadges deps={r.deps} /></td>
                      <td style={{ padding: "8px 10px", textAlign: "right", fontWeight: 700 }}>{r.n_emp_s3d}</td>
                      {tab !== "sem_pdca" && <>
                        {tab === "todos" && <td style={{ padding: "8px 10px" }}><SitBadge sit={r.situacao} /></td>}
                        <td style={{ padding: "8px 10px", textAlign: "right", fontWeight: 700 }}>{r.total || "—"}</td>
                        <td style={{ padding: "8px 10px" }}>{r.tem_pdca ? <ConcBar p={r.conc_p} /> : <span style={{ color: "#CCC" }}>—</span>}</td>
                        {(tab === "todos" || tab === "sem2026" || tab === "sem_fin") && (
                          <td style={{ padding: "8px 10px", textAlign: "right", fontWeight: 700,
                            color: r.atrasados > 0 ? "#DC2626" : "#CCC" }}>{r.atrasados > 0 ? r.atrasados : "—"}</td>
                        )}
                        <td style={{ padding: "8px 10px", fontSize: 11, fontWeight: 600,
                          color: r.tem_2026 ? "#059669" : r.ultima_data ? "#DC2626" : "#CCC" }}>
                          {r.ultima_data || "—"}
                        </td>
                        {(tab === "todos" || tab === "sem_fin") && (
                          <td style={{ padding: "8px 10px", textAlign: "center" }}>
                            {r.tem_pdca ? (r.tem_2026 ? "✅" : "❌") : <span style={{ color: "#CCC" }}>—</span>}
                          </td>
                        )}
                      </>}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Paginação */}
            {totalPages > 1 && (
              <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 10, marginTop: 14 }}>
                <button onClick={() => setPage((p) => Math.max(1, p - 1))} disabled={page === 1}
                  style={{ fontFamily: "inherit", fontSize: 12, padding: "6px 14px", border: "1px solid #E2E2E2",
                    borderRadius: 8, background: "#fff", cursor: page === 1 ? "default" : "pointer",
                    color: page === 1 ? "#CCC" : "#333", opacity: page === 1 ? .4 : 1 }}>
                  ← Anterior
                </button>
                <span style={{ fontSize: 12, color: "#666" }}>Página {page} de {totalPages}</span>
                <button onClick={() => setPage((p) => Math.min(totalPages, p + 1))} disabled={page === totalPages}
                  style={{ fontFamily: "inherit", fontSize: 12, padding: "6px 14px", border: "1px solid #E2E2E2",
                    borderRadius: 8, background: "#fff", cursor: page === totalPages ? "default" : "pointer",
                    color: page === totalPages ? "#CCC" : "#333", opacity: page === totalPages ? .4 : 1 }}>
                  Próxima →
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
